"""Whether generated bytes clear every check a shipped file meets, and a lossless way out for a PNG.

A chart's compressed bytes, or the base64 of a chart embedded in a page, are effectively random, so
by chance they can spell a private term or a client identifier's shape. The client gate's BINARY
limb cannot allowlist a file (PRERELEASE-01 P2), and an allowlist would excuse a real hit later
anyway. The fix is at source: re-encode the PNG losslessly at another compression level until the
bytes the checks read are clear, and refuse if no level clears them.

Used by ``scripts/run_wind_showcase.py --publish`` (SHOWCASESYNC-01) on the charts it writes, and by
the report page's post-render label step (REPORTPAGE-01) on the charts the report embeds. It needs the
client gate's term list, which only the machine that publishes holds; without it, it refuses.
"""
from __future__ import annotations

import io
import os
import sys
from pathlib import Path
from typing import Callable

REPO = Path(__file__).resolve().parents[2]
for _p in (REPO / "scripts", REPO / "scripts" / "release"):
    if str(_p) not in sys.path:
        sys.path.insert(0, str(_p))

import client_gate  # noqa: E402
import name_checks as nc  # noqa: E402

#: (name, bytes as a scanner reads them) -> what it finds. Empty is clear.
Findings = Callable[[str, bytes], list[str]]


def load_findings(repo: Path = REPO) -> Findings:
    """The checks a shipped file meets: the client gate's terms and values, and name_checks'
    client identifiers and scrubbed names. Never prints a term: findings name an index."""
    terms_path = Path(os.environ.get("CLIENT_GATE_TERMS", repo / "terms.local.txt"))
    if not terms_path.is_file():
        raise FileNotFoundError(
            f"the client gate's term list is not here ({terms_path.name}), so these bytes cannot "
            "be shown publishable. Run on the machine that holds it, or set CLIENT_GATE_TERMS.")
    terms, values, _ = client_gate.load_terms(terms_path, repo / "terms.sha256")  # link-rule: the publishing machine checks its term list against the digest the guarded repository keeps
    words = nc.needles()

    def findings(name: str, blob: bytes) -> list[str]:
        low = client_gate.decode_any(blob).lower()
        out = [f"term[{i}]" for i, t in enumerate(terms) if client_gate.term_in_blob(t, blob, low)]
        out += ["a confidential value" for v in values if v.lower() in low]
        out += nc.client_findings(name, blob)
        out += nc.file_findings(name, blob, words)
        return out

    return findings


def clean_png(data: bytes, name: str, findings: Findings,
              view: Callable[[bytes], bytes] = lambda b: b) -> bytes:
    """``data`` unchanged if ``view(data)`` is clear; otherwise the same image re-encoded at the
    first compression level (9 down to 1) whose view is clear. Pixels, text chunks and dpi are
    kept. ``view`` is what the scanner reads: the bytes themselves for a file, base64 for a chart
    embedded in a page."""
    if not findings(name, view(data)):
        return data
    from PIL import Image
    from PIL.PngImagePlugin import PngInfo

    with Image.open(io.BytesIO(data)) as im:
        im.load()
        info = PngInfo()
        for k, v in im.text.items():
            info.add_text(k, v)
        kwargs = {"pnginfo": info}
        if "dpi" in im.info:
            kwargs["dpi"] = im.info["dpi"]
        for level in range(9, 0, -1):
            buf = io.BytesIO()
            im.save(buf, format="PNG", compress_level=level, **kwargs)
            if not findings(name, view(buf.getvalue())):
                return buf.getvalue()
    raise ValueError(f"{name}: trips a shipped-file check at every lossless compression level")
